	u8 newval = ucontrol->value.integer.value[0];
	int err;

	if (oldval == newval)
		return 0;

	kcontrol->private_value &= ~(0xff << 24);
	kcontrol->private_value |= newval;
	err = snd_ni_update_cur_val(list);
	return err < 0 ? err : 1;
}

